function el(tag, cls, text) { var n = document.createElement(tag); if (cls) n.className = cls; if (text) n.textContent = text; return n; }
function ordinal(n) { var s = ["th", "st", "nd", "rd"], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); }
function placeholder(i, cls) { var d = el("div", "ph " + (cls || "") + " ph-empty"); d.appendChild(el("b", "", "â™¡")); d.appendChild(document.createTextNode("Photo " + i)); return d; }
function photo(src, i, alt) {
  if (!src) return placeholder(i);
  var img = new Image(); img.className = "ph"; img.alt = alt || "Khirk and Daphne"; img.loading = "lazy"; img.decoding = "async"; img.src = src;
  img.onerror = function () { img.replaceWith(placeholder(i)); };
  return img;
}
function utc(y, m, d) { return Date.UTC(y, m - 1, d); }
function renderCounter() {
  var now = new Date(), ty = now.getFullYear(), tm = now.getMonth() + 1, td = now.getDate();
  var days = Math.max(0, Math.round((utc(ty, tm, td) - utc(START.y, START.m, START.d)) / 86400000));
  document.getElementById("days").textContent = days.toLocaleString();
  var y = ty - START.y, m = tm - START.m, d = td - START.d;
  if (d < 0) { m -= 1; d += new Date(ty, tm - 1, 0).getDate(); }
  if (m < 0) { y -= 1; m += 12; }
  var parts = [];
  if (y > 0) parts.push(y + (y === 1 ? " year" : " years"));
  if (m > 0) parts.push(m + (m === 1 ? " month" : " months"));
  if (d > 0) parts.push(d + (d === 1 ? " day" : " days"));
  document.getElementById("ymd").textContent = parts.join(", ");
  var until = document.getElementById("until");
  if (tm === START.m && td === START.d && y > 0) { until.textContent = "Happy " + ordinal(y) + " anniversary, love."; return; }
  var nextN = y + 1;
  var diff = Math.round((utc(START.y + nextN, START.m, START.d) - utc(ty, tm, td)) / 86400000);
  until.textContent = diff === 1 ? "One more day until our " + ordinal(nextN) + " anniversary." : diff + " days until our " + ordinal(nextN) + " anniversary.";
}
function build() {
  var story = document.getElementById("story");
  STORY.forEach(function (s, i) {
    var scene = el("section", "scene"), print = el("div", "print rise");
    print.style.setProperty("--tilt", (i % 2 ? 1.4 : -1.4) + "deg");
    print.appendChild(photo(s.src, i + 1, s.cap)); scene.appendChild(print);
    if (s.cap) scene.appendChild(el("p", "cap rise", s.cap));
    if (s.msg) scene.appendChild(el("p", "msg rise", s.msg));
    story.appendChild(scene);
  });
  buildSpots();
  var letter = document.getElementById("letter");
  LETTER.forEach(function (t) { letter.appendChild(el("p", LETTER_IS_DRAFT ? "draft rise" : "rise", t)); });
  document.getElementById("sign").textContent = SIGN;
  var io = "IntersectionObserver" in window ? new IntersectionObserver(function (es) {
    es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } });
  }, { threshold: 0.15 }) : null;
  document.querySelectorAll(".rise").forEach(function (n) { if (io) io.observe(n); else n.classList.add("in"); });
}
function openBox(src, i) {
  var box = el("div", "lightbox"); box.setAttribute("role", "dialog"); box.setAttribute("aria-modal", "true");
  box.appendChild(photo(src, i));
  var x = el("button", "", "Ã—"); x.type = "button"; x.setAttribute("aria-label", "Close photo");
  function close() { box.remove(); document.removeEventListener("keydown", onKey); }
  function onKey(e) { if (e.key === "Escape") close(); }
  x.addEventListener("click", close);
  box.addEventListener("click", function (e) { if (e.target === box) close(); });
  document.addEventListener("keydown", onKey);
  box.appendChild(x); document.body.appendChild(box); x.focus();
}
var song = document.getElementById("song"), musicBtn = document.getElementById("music");
function setMusicUi(on) {
  musicBtn.classList.toggle("on", on);
  musicBtn.setAttribute("aria-label", on ? "Pause music" : "Play music");
  document.getElementById("musicLabel").textContent = on ? "Bawat Daan" : "Play music";
}
function fadeIn() { song.volume = 0; var v = 0, t = setInterval(function () { v = Math.min(1, v + 0.05); song.volume = v; if (v >= 1) clearInterval(t); }, 120); }
function begin() {
  document.getElementById("gate").classList.add("gone");document.body.classList.add("started");
  document.body.classList.remove("locked");
  musicBtn.hidden = false;
  var p = song.play(); fadeIn();
  if (p && p.then) p.then(function () { setMusicUi(true); }, function () { setMusicUi(false); }); else setMusicUi(true);
  window.scrollTo(0, 0);
}
musicBtn.addEventListener("click", function () {
  if (song.paused) { song.volume = 1; var p = song.play(); if (p && p.catch) p.catch(function () {}); setMusicUi(true); }
  else { song.pause(); setMusicUi(false); }
});
document.getElementById("begin").addEventListener("click", begin);
document.body.classList.add("locked");
(function stars() {
  var c = document.getElementById("stars"), g = c.getContext("2d"), dots = [], lanterns = [], W = 0, H = 0;
  var still = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  function size() {
    var r = Math.min(window.devicePixelRatio || 1, 2); W = window.innerWidth; H = window.innerHeight;
    c.width = W * r; c.height = H * r; g.setTransform(r, 0, 0, r, 0, 0);
    dots = []; for (var i = 0; i < 70; i++) dots.push({ x: Math.random() * W, y: Math.random() * H, r: Math.random() * 1.3 + 0.3, p: Math.random() * 6.28, s: Math.random() * 0.8 + 0.3 });
    lanterns = [];
    var lanternCount = W < 600 ? 16 : 26;
    for (var j = 0; j < lanternCount; j++) lanterns.push({
      x: Math.random() * W, y: Math.random() * (H + 220),
      w: 12 + Math.random() * 8, h: 18 + Math.random() * 10,
      speed: 4 + Math.random() * 7, sway: 8 + Math.random() * 16,
      phase: Math.random() * 6.28, a: 0.42 + Math.random() * 0.28
    });
  }
  function draw(t) {
    g.clearRect(0, 0, W, H);
    for (var i = 0; i < dots.length; i++) {
      var d = dots[i], a = 0.25 + 0.5 * (0.5 + 0.5 * Math.sin(d.p + (still ? 0 : t / 1000) * d.s));
      g.beginPath(); g.fillStyle = (i % 5 === 0 ? "rgba(255,157,181," : "rgba(244,236,234,") + a + ")"; g.arc(d.x, d.y, d.r, 0, 6.28); g.fill();
    }
    var seconds = still ? 0 : t / 1000;
    lanterns.forEach(function (l) {
      var y = still ? l.y : (l.y - seconds * l.speed) % (H + 240);
      if (y < -120) y += H + 240;
      var x = l.x + (still ? 0 : Math.sin(seconds * 0.18 + l.phase) * l.sway);
      g.save(); g.translate(x, y); g.globalAlpha = l.a;
      g.shadowColor = "rgba(255, 177, 99, 0.9)"; g.shadowBlur = 14;
      g.beginPath();
      g.moveTo(-l.w * 0.5, -l.h * 0.35);
      g.quadraticCurveTo(-l.w * 0.62, 0, -l.w * 0.42, l.h * 0.5);
      g.lineTo(l.w * 0.42, l.h * 0.5);
      g.quadraticCurveTo(l.w * 0.62, 0, l.w * 0.5, -l.h * 0.35);
      g.closePath(); g.fillStyle = "rgba(255, 184, 112, 0.86)"; g.fill();
      g.shadowBlur = 0; g.strokeStyle = "rgba(255, 232, 177, 0.78)"; g.lineWidth = 0.8; g.stroke();
      g.beginPath(); g.moveTo(-l.w * 0.36, -l.h * 0.35);
      g.quadraticCurveTo(0, -l.h * 0.48, l.w * 0.36, -l.h * 0.35); g.stroke();
      g.restore();
    });
    if (!still) requestAnimationFrame(draw);
  }
  size(); window.addEventListener("resize", size); requestAnimationFrame(draw);
})();

