function toast(msg){
  var box=$("toasts"),n=el("div","toast",msg);box.appendChild(n);
  while(box.children.length>3)box.removeChild(box.firstChild);
  setTimeout(function(){n.classList.add("out");setTimeout(function(){n.remove();},400);},2800);
}
/* particles: one shared canvas loop (from the Balance Exchange badge burst) */
var PAL={rect:["#ff9db5","#f3d3a2","#ffffff"],heart:["#ff9db5","#ff6b8b","#ffffff"],spark:["#f3d3a2","#ffffff","#fff3c4"],ember:["#f3d3a2","#ffb347","#ffe9a8"],petal:["#ffc2d4","#ff9db5","#ffe0ea"],feather:["#ffffff","#e8e4ff"],bubble:["#ffffff","#cfe9ff"]};
var parts=[],running=false;
function spawn(cx,cy,spec){
  if(reduce)return;
  var cv=$("burst"),ctx=cv.getContext("2d"),dpr=Math.min(window.devicePixelRatio||1,2);
  if(!running){cv.width=innerWidth*dpr;cv.height=innerHeight*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
  cv.classList.add("on");
  var rose=getComputedStyle(document.documentElement).getPropertyValue("--rose").trim()||"#ff9db5";
  for(var i=0;i<spec.n;i++){
    var kind=spec.k[i%spec.k.length],pal=PAL[kind].slice();if(kind==="rect"||kind==="heart")pal[0]=rose;
    var a=Math.random()*6.283,s=(.35+Math.random())*spec.sp;
    parts.push({kind:kind,x:cx,y:cy,vx:Math.cos(a)*s,vy:Math.sin(a)*s-(spec.lift||0),g:spec.g,c:pal[i%pal.length],l:1,dec:(spec.decay||.014)*(.8+Math.random()*.5),w:kind==="spark"?2+Math.random()*2:3+Math.random()*4,rot:Math.random()*6,vr:(Math.random()-.5)*.3,ph:Math.random()*6,sw:kind==="petal"||kind==="feather"?.6:0,swarm:spec.swarm});
  }
  if(running)return;running=true;
  (function loop(){
    ctx.clearRect(0,0,innerWidth,innerHeight);var alive=0;
    parts.forEach(function(p){
      if(p.swarm){p.vx+=(Math.random()-.5)*.5;p.vy+=(Math.random()-.5)*.5;}
      p.ph+=.1;p.x+=p.vx+Math.sin(p.ph)*p.sw;p.y+=p.vy;p.vy+=p.g;p.vx*=.985;p.l-=p.dec;p.rot+=p.vr;
      if(p.l<=0)return;alive++;
      ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.globalAlpha=Math.max(0,Math.min(1,p.l*1.4));ctx.fillStyle=p.c;ctx.strokeStyle=p.c;var w=p.w;
      if(p.kind==="rect")ctx.fillRect(-w/2,-w/4,w,w/2);
      else if(p.kind==="heart"){ctx.font=(w*3)+"px serif";ctx.textAlign="center";ctx.fillText("\u2665",0,0);}
      else if(p.kind==="spark"){ctx.beginPath();ctx.moveTo(0,-w*1.6);ctx.lineTo(w*.3,-w*.3);ctx.lineTo(w*1.6,0);ctx.lineTo(w*.3,w*.3);ctx.lineTo(0,w*1.6);ctx.lineTo(-w*.3,w*.3);ctx.lineTo(-w*1.6,0);ctx.lineTo(-w*.3,-w*.3);ctx.closePath();ctx.fill();}
      else if(p.kind==="ember"){ctx.beginPath();ctx.arc(0,0,w*.6,0,6.283);ctx.fill();}
      else if(p.kind==="petal"){ctx.beginPath();ctx.ellipse(0,0,w*1.1,w*.55,0,0,6.283);ctx.fill();}
      else if(p.kind==="feather"){ctx.beginPath();ctx.ellipse(0,0,w*1.4,w*.4,0,0,6.283);ctx.fill();}
      else if(p.kind==="bubble"){ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(0,0,w*1.2,0,6.283);ctx.stroke();}
      ctx.restore();
    });
    parts=parts.filter(function(p){return p.l>0;});
    if(alive)requestAnimationFrame(loop);else{ctx.clearRect(0,0,innerWidth,innerHeight);cv.classList.remove("on");running=false;}
  })();
}
function tilt(b){
  if(reduce)return;var raf=0,host=b.parentNode.parentNode;
  host.addEventListener("pointermove",function(e){
    if(e.pointerType==="touch"||b.className.indexOf("fx-")>-1)return;var r=host.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
    cancelAnimationFrame(raf);raf=requestAnimationFrame(function(){b.style.transform="perspective(500px) rotateX("+(-y*24).toFixed(1)+"deg) rotateY("+(x*28).toFixed(1)+"deg) scale(1.12)";});
  });
  host.addEventListener("pointerleave",function(){cancelAnimationFrame(raf);b.style.transform="";});
}
function updateRing(){
  var n=opened.length;
  $("ringBar").style.strokeDashoffset=100-n*100/TOTAL;$("ringNum").textContent=n+"/"+TOTAL;
  $("ring").classList.toggle("full",n>=TOTAL);
}
function makeSpot(sp){
  var T=TYPES[sp.t],b=el("button","spot t-"+sp.t);b.type="button";
  b.style.left=sp.x+"%";b.style.top=(sp.y||50)+"%";
  b.style.setProperty("--r",(sp.r!==undefined?sp.r:((sp.i%2?1:-1)*(4+sp.i%7)))+"deg");
  b.style.setProperty("--d",(-(sp.i%7)*.6)+"s");
  b.setAttribute("aria-label","Hidden memory: "+T.label);
  b.innerHTML='<span class="fl"><span class="ping"></span><span class="ico" aria-hidden="true">'+T.e+'</span></span>';
  var th=new Image();th.className="thumb";th.alt="";th.src=GALLERY[sp.i];b.firstChild.appendChild(th);
  if(opened.indexOf(sp.i)>-1)b.classList.add("done");
  tilt(b.querySelector(".ico"));
  b.addEventListener("click",function(){openSpot(sp,b);});
  return b;
}
function buildSpots(){
  var story=$("story"),hero=document.querySelector(".intro"),letter=document.querySelector(".letter"),field=$("field"),st={};
  function stash(h){var s=el("div","stash");s.style.height=h+"px";return s;}
  st.hero=stash(84);hero.insertBefore(st.hero,hero.querySelector(".scroll-hint"));
  Array.prototype.forEach.call(story.querySelectorAll(".scene"),function(sc,k){st["s"+k]=stash(92);sc.parentNode.insertBefore(st["s"+k],sc.nextSibling);});
  st.letter=stash(96);letter.insertBefore(st.letter,letter.querySelector(".heart"));
  SPOTS.forEach(function(sp){
    var host=sp.w==="hero"?st.hero:sp.w==="story"?st["s"+sp.k]:sp.w==="letter"?st.letter:field;
    if(host)host.appendChild(makeSpot(sp));
  });
  updateRing();
}
function openSpot(sp,b){
  var r=b.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;current=b;
  if(b.classList.contains("done")){showMemory(sp.i,cx,cy);return;}
  if(busy)return;busy=true;
  var T=TYPES[sp.t],ico=b.querySelector(".ico");ico.style.transform="";b.classList.add("opening");
  if(!reduce)ico.classList.add("fx-"+T.fx);
  var wait=reduce?0:T.wait;
  setTimeout(function(){spawn(cx,cy,T.spec);},reduce?0:wait*.35);
  setTimeout(function(){
    b.classList.remove("opening");b.classList.add("done");
    if(opened.indexOf(sp.i)<0)opened.push(sp.i);saveOpened();updateRing();
    toast("Memory "+opened.length+" of "+TOTAL+" found");showMemory(sp.i,cx,cy);busy=false;
  },wait+140);
}
function pending(){return Array.prototype.filter.call(document.querySelectorAll(".spot"),function(s){return !s.classList.contains("done");});}
function nextFrom(y){
  var l=pending().map(function(s){return {s:s,y:s.getBoundingClientRect().top+window.scrollY};}).sort(function(a,b){return a.y-b.y;});
  if(!l.length)return null;for(var k=0;k<l.length;k++)if(l[k].y>y+30)return l[k].s;return l[0].s;
}
function goTo(s,msg){
  if(!s)return;s.scrollIntoView({behavior:reduce?"auto":"smooth",block:"center"});
  setTimeout(function(){s.focus({preventScroll:true});if(s.animate)s.animate([{transform:"rotate("+(s.style.getPropertyValue("--r")||"0deg")+") scale(1)"},{transform:"rotate(0deg) scale(1.35)"},{transform:"rotate("+(s.style.getPropertyValue("--r")||"0deg")+") scale(1)"}],{duration:600});},reduce?0:550);
  if(msg)toast(msg);
}
function showMemory(i,cx,cy){
  var card=$("card");
  card.style.setProperty("--dx",(cx-innerWidth/2)+"px");card.style.setProperty("--dy",(cy-innerHeight/2)+"px");
  $("popImg").src=GALLERY[i];$("popMsg").textContent=PHOTO_CAPTIONS[i]||"";
  $("popNext").hidden=pending().length===0;
  card.style.animation="none";void card.offsetWidth;card.style.animation="";
  $("pop").classList.add("on");$("popClose").focus();
}
function closeMemory(){
  $("pop").classList.remove("on");
  if(current)current.focus({preventScroll:true});
  if(opened.length>=TOTAL&&!finaleSeen()){finaleMark();finale();}
}
function finaleSeen(){try{return localStorage.getItem("kd-finale")==="1";}catch(e){return false;}}
function finaleMark(){try{localStorage.setItem("kd-finale","1");}catch(e){}}
function finale(){
  toast("You found every memory \u2665 Happy 2nd anniversary!");
  [[.25,.35],[.75,.3],[.5,.55],[.5,.2]].forEach(function(p,k){setTimeout(function(){spawn(innerWidth*p[0],innerHeight*p[1],{k:["rect","heart","spark"],n:110,sp:9,g:.22,lift:4});},k*280);});
}
$("popClose").addEventListener("click",closeMemory);
$("pop").addEventListener("click",function(e){if(e.target===$("pop"))closeMemory();});
document.addEventListener("keydown",function(e){if(e.key==="Escape"&&$("pop").classList.contains("on"))closeMemory();});
$("popNext").addEventListener("click",function(){
  var y=current?current.getBoundingClientRect().top+window.scrollY:window.scrollY;
  $("pop").classList.remove("on");goTo(nextFrom(y),"Another one is hiding nearbyâ€¦");
});
$("hud").addEventListener("click",function(){
  if(!pending().length){toast("You found them all \u2665");return;}
  goTo(nextFrom(window.scrollY+innerHeight*.5),"Look closely, something is hiding here");
});
$("resetBoxes").addEventListener("click",function(){
  opened=[];saveOpened();try{localStorage.removeItem("kd-finale");}catch(e){}
  document.querySelectorAll(".spot").forEach(function(b){b.classList.remove("done","opening");var i=b.querySelector(".ico");i.className="ico";i.style.transform="";});
  updateRing();toast("All hidden again");
});
/* proposal choices */
(function(){
  var lg=$("login"),card=$("lcard"),yes=$("yes"),done=false,btns=lg.querySelectorAll(".lchoices button");
  if(btns[0])btns[0].focus({preventScroll:true});
  btns.forEach(function(b){b.addEventListener("click",function(){
    if(done)return;done=true;b.classList.add("pick");card.classList.add("sent");
    setTimeout(function(){
      lg.classList.add("said");yes.classList.add("on");
      var w=innerWidth,h=innerHeight;
      [[.5,.45],[.2,.3],[.8,.3],[.35,.7],[.65,.7]].forEach(function(p,k){setTimeout(function(){spawn(w*p[0],h*p[1],{k:["heart","rect","spark"],n:90,sp:9,g:.2,lift:4});},k*220);});
    },reduce?0:450);
    setTimeout(function(){
      lg.classList.add("gone");
      setTimeout(function(){lg.remove();var bg=$("begin");if(bg)bg.focus({preventScroll:true});},reduce?0:950);
    },reduce?1800:3300);
  });});
})();

/* nav + color themes */
var menuBtn=$("menuBtn"),nav=$("mainNav");
menuBtn.addEventListener("click",function(){var o=nav.classList.toggle("open");menuBtn.setAttribute("aria-expanded",o);});
nav.addEventListener("click",function(e){if(e.target.tagName==="A"){nav.classList.remove("open");menuBtn.setAttribute("aria-expanded","false");}});
function setTheme(n,silent){
  document.documentElement.setAttribute("data-theme",n);
  document.querySelectorAll(".themes button").forEach(function(b){b.setAttribute("aria-pressed",b.getAttribute("data-th")===n);});
  try{localStorage.setItem("kd-theme",n);}catch(e){}
  if(!silent)toast(n.charAt(0).toUpperCase()+n.slice(1)+" color on");
}
document.querySelectorAll(".themes button").forEach(function(b){b.addEventListener("click",function(){setTheme(b.getAttribute("data-th"));});});
var savedTheme=null;try{savedTheme=localStorage.getItem("kd-theme");}catch(e){}
if(["rose","lilac","sage","sky"].indexOf(savedTheme)>-1)setTheme(savedTheme,true);
build(); renderCounter();
